def thanos_sort_max_length(n, arr):
    from functools import lru_cache

    @lru_cache(None)
    def max_sorted_length(start, end):
        if start >= end:
            return 0
        if end - start == 1:
            return 1

        mid = (start + end) // 2
        left_sorted = max_sorted_length(start, mid)
        right_sorted = max_sorted_length(mid, end)

        # Check if the whole segment is sorted
        if all(arr[i] <= arr[i + 1] for i in range(start, end - 1)):
            return end - start

        # Check if the left half is sorted
        if all(arr[i] <= arr[i + 1] for i in range(start, mid - 1)):
            left_sorted = mid - start

        # Check if the right half is sorted
        if all(arr[i] <= arr[i + 1] for i in range(mid, end - 1)):
            right_sorted = end - mid

        return max(left_sorted, right_sorted)

    return max_sorted_length(0, n)

