def thanos_sort_max_sorted_length(n, arr):
    # Helper function to check if a subarray is sorted
    def is_sorted(subarr):
        return all(subarr[i] <= subarr[i + 1] for i in range(len(subarr) - 1))

    # Recursive function to find the maximum length of a sorted subarray using Thanos sort
    def max_sorted_length(start, end):
        if start == end:
            return 1
        if is_sorted(arr[start:end + 1]):
            return end - start + 1

        mid = (start + end) // 2
        # Consider removing the first half or the second half
        return max(max_sorted_length(start, mid), max_sorted_length(mid + 1, end))

    return max_sorted_length(0, n - 1)

